statement:
You are hungry and want to reach food as fast as possible. The map is a character matrix `grid` whose cells are:

- `'*'`: where you start (there is exactly one such cell);
- `'#'`: a food cell (there may be any number of them, including none);
- `'O'`: open ground you can walk through;
- `'X'`: an obstacle you cannot enter.

Each step moves you to a neighbouring cell up, down, left or right that is not an obstacle and is inside the grid. Return the smallest number of steps needed to stand on any food cell, or `-1` if no food cell can be reached.

validator:
function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 200) return 'grid needs 1 to 200 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 200) return 'Each row needs 1 to 200 cells.';
  let starts = 0;
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    for (const cell of row) {
      if (!['*', '#', 'O', 'X'].includes(cell)) return "Cells must be '*', '#', 'O' or 'X'.";
      if (cell === '*') starts++;
    }
  }
  if (starts !== 1) return "The grid needs exactly one '*'.";
  return null;
}

