function getFood(grid) {
  // Relax distances over the whole grid until nothing changes (Bellman-Ford style).
  const m = grid.length, n = grid[0].length;
  const dist = grid.map(row => row.map(cell => (cell === '*' ? 0 : Infinity)));
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < m; i++)
      for (let j = 0; j < n; j++) {
        if (grid[i][j] === 'X') continue;
        for (const [a, b] of [[i - 1, j], [i + 1, j], [i, j - 1], [i, j + 1]]) {
          if (a < 0 || b < 0 || a >= m || b >= n || grid[a][b] === 'X') continue;
          if (dist[a][b] + 1 < dist[i][j]) { dist[i][j] = dist[a][b] + 1; changed = true; }
        }
      }
  }
  let answer = Infinity;
  for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) if (grid[i][j] === '#') answer = Math.min(answer, dist[i][j]);
  return answer === Infinity ? -1 : answer;
}

