function generate(rand, size) {
  const m = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const wall = size === 'large' ? 0.25 + rand() * 0.15 : rand() * 0.5;
  const food = size === 'large' ? rand() * 0.002 : rand() * 0.3;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => {
    const x = rand();
    return x < wall ? 'X' : x < wall + food ? '#' : 'O';
  }));
  grid[Math.floor(rand() * m)][Math.floor(rand() * n)] = '*';
  return [grid];
}
